def distance(a, b):
    dx = a[0] - b[0]
    dy = a[1] - b[1]
    if dx < 0:
        dx = -dx
    if dy < 0:
        dy = -dy
    return dx + dy

def race_margin(player, target, rivals):
    steps = distance(player, target)
    lead = 1
    if len(rivals) > 0:
        nearest = distance(rivals[0], target)
        for rival in rivals:
            other = distance(rival, target)
            if other < nearest:
                nearest = other
        lead = nearest - steps
    return [steps, lead]

def choose_supply(player, targets, rivals):
    best = None
    best_steps = 0
    best_lead = 0
    for target in targets:
        race = race_margin(player, target, rivals)
        steps = race[0]
        lead = race[1]
        if steps == 0:
            return target
        safe = lead > 0
        best_safe = best_lead > 0
        if best is None or (safe and not best_safe) or (safe == best_safe and (steps < best_steps or (steps == best_steps and lead > best_lead))):
            best = target
            best_steps = steps
            best_lead = lead
    return best
